-- Queer Atlas: exactly four researched hotels for Lille, Corfu, Chania, Cork and Innsbruck.
-- Idempotent; all accommodation rows use the production-approved type 'hotel'.

begin;

alter table if exists public.places add column if not exists venue_intel jsonb not null default '{}'::jsonb;

with raw_hotels as (
 select * from jsonb_to_recordset($qa_hotels$
[
 {"name":"Moxy Lille City","aliases":"Moxy Lille City|Moxy Lille","city":"lille","description":"A former medical faculty transformed into a theatrical red-brick Moxy, where vaulted stone, neon wit and a lively bar put queer travellers between the centre and Moulins.","vibe":"playful heritage hotel with an energetic all-hours lobby","tags":"social,cultural,cozy","hours":"Reception and lobby bar operate 24 hours; breakfast, gym and parking vary.","link":"https://www.marriott.com/en-us/hotels/lilox-moxy-lille-city/overview/","location":"3 Rue Jean Bart, 59000 Lille, France","lat":50.62712,"lng":3.06380,"arrival":"The historic building has varied room geometry; confirm adapted room, lift route and parking before arrival.","best":"Best for design-conscious visitors wanting a sociable base near Pride and central bars.","crowd":"LGBTQ+ couples and solo travellers mix with students, creatives and city-break guests.","dress":"Playful city casual.","inclusion":"Covered by Marriott's explicit global LGBTQ+ inclusion and equal-opportunity commitments; no local queer ownership claim.","basis":"Active first-party hotel source plus current corporate inclusion framework.","class":"Upper-midscale Moxy lifestyle hotel","coords":"Exact official address checked 2026-08-28.","sources":["https://www.marriott.com/en-us/hotels/lilox-moxy-lille-city/overview/","https://www.marriott.com/culture-and-values/diversity-and-inclusion.mi"]},
 {"name":"Mama Shelter Lille","aliases":"Mama Shelter Lille|Mama Lille","city":"lille","description":"A cheeky, graphic hotel opposite Lille-Flandres with rooftop energy, communal tables and bedrooms that turn cartoon masks and concrete into part of the night's costume.","vibe":"irreverent urban clubhouse beside the station","tags":"social,cultural,mixed","hours":"Reception operates 24 hours; restaurant, rooftop and events vary.","link":"https://mamashelter.com/lille/","location":"97 Place Saint-Hubert, 59800 Lille, France","lat":50.63824,"lng":3.06908,"arrival":"Station crowds and event nights can complicate drop-off; ask for a quiet or adapted room explicitly.","best":"Best for queer friends who want a fun lobby and immediate station-to-nightlife access.","crowd":"LGBTQ+ guests mix with young professionals, weekend groups, diners and rail travellers.","dress":"Bold casual to rooftop-ready.","inclusion":"Mama Shelter's Accor/Ennismore group operates under published diversity and LGBTQ+ workplace commitments.","basis":"Active official property evidence and current group inclusion policy; no Pride-partner claim.","class":"Lifestyle boutique hotel","coords":"Exact official address checked 2026-08-28.","sources":["https://mamashelter.com/lille/","https://group.accor.com/en/commitment/people-and-communities/diversity-inclusion"]},
 {"name":"Hôtel Barrière Lille","aliases":"Hôtel Barrière Lille|Hotel Barriere Lille|Barrière Lille","city":"lille","description":"A glass-and-copper landmark beside Lille-Europe combining spacious rooms, theatre, casino and serious dining for travellers who want the whole late evening under one roof.","vibe":"full-service urban resort with polished after-dark glamour","tags":"luxury,social,relax","hours":"Reception operates 24 hours; casino, theatre, spa and restaurants have separate schedules.","link":"https://www.hotelsbarriere.com/lille","location":"777 bis Pont de Flandres, 59777 Lille, France","lat":50.63893,"lng":3.07546,"arrival":"Casino crowds and the multi-use complex need precise taxi drop-off; confirm adapted access and gaming age rules.","best":"Best for couples wanting upscale recovery, rail convenience and entertainment without a late walk.","crowd":"LGBTQ+ couples mix with theatre, casino, business and international rail guests.","dress":"Smart-casual; casino and dining rooms may be sharper.","inclusion":"Groupe Barrière publishes equality and diversity commitments; selection does not imply queer ownership.","basis":"Current corporate responsibility evidence paired with active first-party property details.","class":"Five-star casino and theatre hotel","coords":"Exact official address checked 2026-08-28.","sources":["https://www.hotelsbarriere.com/lille","https://www.groupebarriere.com/en/our-commitments/"]},
 {"name":"OKKO Hotels Lille Centre","aliases":"OKKO Hotels Lille Centre|OKKO Lille Centre|OKKO Lille","city":"lille","description":"A crisp central hotel whose guests-only Club supplies all-day drinks, snacks and work space, creating an easy decompression chamber between old-town wandering and queer nightlife.","vibe":"calm design hotel with a genuinely useful communal club","tags":"cozy,cultural,relax","hours":"Reception and guest Club operate 24 hours; sauna and breakfast vary.","link":"https://www.okkohotels.com/en/page/lille-centre-hotel.19326.html","location":"13 Rue d'Amiens, 59800 Lille, France","lat":50.63419,"lng":3.06174,"arrival":"Pedestrian-centre access complicates car arrival; confirm garage route and adapted room directly.","best":"Best for couples and solo guests wanting a quiet central retreat after Pride or the bars.","crowd":"LGBTQ+ city-break guests mix with business travellers, design-minded couples and shoppers.","dress":"Minimalist city casual.","inclusion":"Included on current LGBTQ-welcoming Lille accommodation catalogues and supported by an active official property source; no ownership claim.","basis":"Current specialist inclusion signal plus first-party hotel information.","class":"Four-star French design hotel","coords":"Exact official address checked 2026-08-28.","sources":["https://www.okkohotels.com/en/page/lille-centre-hotel.19326.html","https://www.expedia.com/Lille-Hotels-LGBTQ-Welcoming-Hotel.0-0-d6035307-tLGBTQWelcomingHotel.Travel-Guide-Filter-Hotels"]},

 {"name":"GAY CORFU Guesthouse","aliases":"GAY CORFU Guesthouse|Gay Corfu Guesthouse|GAY CORFU accommodation","city":"corfu","description":"A tiny Benitses guesthouse run by two gay hosts, only steps from the beach, where personal island knowledge and real community recognition matter more than resort-scale amenities.","vibe":"intimate gay-run beach-village base with host-led local connection","tags":"cozy,social,relax","hours":"Small-property arrival by arrangement; confirm season, check-in and transfers directly.","link":"https://www.gayout.com/europe/greece/corfu/hotels/gay-corfu-guesthouse","location":"Benitses 49084, Corfu, Greece","lat":39.54384,"lng":19.91314,"arrival":"No conventional 24-hour desk is assumed; arrange arrival, stairs, exact pin and transport with the hosts.","best":"Best for gay solo travellers or couples prioritising genuine welcome and Benitses beach life.","crowd":"Gay and lesbian travellers, repeat guests, couples and friends seeking a personal stay.","dress":"Beach-village casual.","inclusion":"Current 2026 guest evidence identifies the property as gay-run and deliberately LGBTQ-focused.","basis":"Recent named specialist profile and current guest reviews; direct-booking mechanics must be confirmed.","class":"Small independent guesthouse","coords":"Benitses locality confirmed; request the exact entrance pin from hosts.","sources":["https://www.gayout.com/europe/greece/corfu/hotels/gay-corfu-guesthouse"]},
 {"name":"Angsana Corfu Resort & Spa","aliases":"Angsana Corfu Resort & Spa|Angsana Corfu","city":"corfu","description":"A hillside wellness resort above Benitses where a huge infinity pool appears to pour into the Ionian Sea and Vertigo's adults-only rooftop turns sunset into a polished ritual.","vibe":"panoramic spa luxury with a sophisticated adults-only rooftop","tags":"luxury,relax,social","hours":"Reception operates 24 hours; pools, spa, beach club, restaurants and seasonal bars vary.","link":"https://www.angsana.com/greece/corfu","location":"11th km National Road Corfu to Benitses, Akra Punta, Benitses 49084, Greece","lat":39.55673,"lng":19.90493,"arrival":"The steep resort layout and seasonal shuttle require access planning; confirm adapted route and rooftop closing date.","best":"Best for couples wanting serious spa recovery near Benitses and GAY CORFU's local anchor.","crowd":"LGBTQ+ couples mix with international luxury, wellness, wedding and family guests.","dress":"Resort polish; smarter for Vertigo and signature dining.","inclusion":"Banyan Group publishes diversity and equal-opportunity commitments; adults-only rooftop creates a couple-friendly social option without a queer-exclusive claim.","basis":"Current first-party resort and corporate responsibility evidence.","class":"Five-star Banyan Group resort","coords":"Exact official resort address checked 2026-08-28.","sources":["https://www.angsana.com/greece/corfu","https://www.angsana.com/greece/corfu/dining/vertigo-sky-bar"]},
 {"name":"Domes Miramare, a Luxury Collection Resort, Corfu","aliases":"Domes Miramare, a Luxury Collection Resort, Corfu|Domes Miramare|Domes Miramare Corfu","city":"corfu","description":"An adults-only olive-grove retreat on Moraitika's waterfront, blending mid-century royal history, private beach and discreet pavilion luxury into an exceptionally calm couples' escape.","vibe":"adults-only Ionian glamour with private-beach composure","tags":"luxury,relax,cultural","hours":"Seasonal resort reception operates 24 hours; restaurants, spa, boats and beach services vary.","link":"https://www.marriott.com/en-us/hotels/cfulc-domes-miramare-a-luxury-collection-resort-corfu/overview/","location":"Moraitika, Corfu 49084, Greece","lat":39.48791,"lng":19.92228,"arrival":"The resort is well south of Corfu Town; pre-book transfer and confirm adapted beach access.","best":"Best for queer couples seeking privacy, adult quiet and a destination stay rather than nightlife.","crowd":"LGBTQ+ couples mix with international luxury, honeymoon and yachting guests.","dress":"Refined resort casual.","inclusion":"Covered by Marriott's explicit LGBTQ+ inclusion framework; adults-only status is factual but not itself an inclusion claim.","basis":"Active Luxury Collection property plus current corporate inclusion policy.","class":"Five-star adults-only Luxury Collection resort","coords":"Exact official locality checked 2026-08-28.","sources":["https://www.marriott.com/en-us/hotels/cfulc-domes-miramare-a-luxury-collection-resort-corfu/overview/","https://www.marriott.com/culture-and-values/diversity-and-inclusion.mi"]},
 {"name":"Cook's Club Corfu","aliases":"Cook's Club Corfu|Cooks Club Corfu","city":"corfu","description":"An adults-only Gouvia hideout with jungle-like pools, DJs, open kitchens and a free-spirited design language that suits queer friends who want social resort energy without family programming.","vibe":"lush adults-only social resort with DJ-led pool energy","tags":"social,relax,mixed","hours":"Seasonal reception operates 24 hours; pools, restaurants, DJs and transfers vary.","link":"https://www.cooksclub.com/hotels/corfu/","location":"6th km Ethnikis Palaiokastritsas, Gouvia, Corfu 49100, Greece","lat":39.65439,"lng":19.84363,"arrival":"The resort sits outside Corfu Town; confirm season, shuttle, accessible room and late taxi plan.","best":"Best for queer groups wanting an adults-only social base between town and northern beaches.","crowd":"LGBTQ+ friends and couples mix with young international leisure and music-focused guests.","dress":"Pool-to-DJ resort casual.","inclusion":"Current LGBTQ-welcoming accommodation catalogues include the property; no gay ownership or dedicated programming is claimed.","basis":"Specialist inclusion signal paired with current first-party property information.","class":"Adults-only lifestyle resort","coords":"Exact official address checked 2026-08-28.","sources":["https://www.cooksclub.com/hotels/corfu/","https://www.expedia.com/Corfu-Hotels-LGBTQ-Welcoming-Hotel.0-0-d816-tLGBTQWelcomingHotel.Travel-Guide-Filter-Hotels"]},

 {"name":"Chania Flair Boutique Hotel, Tapestry Collection by Hilton","aliases":"Chania Flair Boutique Hotel, Tapestry Collection by Hilton|Chania Flair Boutique Hotel|Chania Flair","city":"chania","description":"An adults-only design hotel near Nea Chora whose rooftop infinity pool, sculptural rooms and seafront sunsets offer a polished counterpoint to the old town's summer crowds.","vibe":"adults-only rooftop calm within walking distance of Chania nightlife","tags":"luxury,relax,cultural","hours":"Reception operates 24 hours; rooftop pool, spa, breakfast and bar vary.","link":"https://www.hilton.com/en/hotels/chqflup-chania-flair-boutique-hotel/","location":"Petrof 61 and Palaiologou, Chania 73131, Greece","lat":35.51424,"lng":24.00902,"arrival":"Old-city parking and compact streets require advance transfer planning; confirm adapted room and rooftop access.","best":"Best for queer couples wanting adult quiet, sea swims and a walkable route to Apollo nights.","crowd":"LGBTQ+ couples mix with design, wellness and international leisure guests.","dress":"Elevated island casual.","inclusion":"Hilton publishes explicit LGBTQ+ welcoming-travel and workplace commitments.","basis":"Current corporate inclusion evidence plus active first-party property page.","class":"Five-star adults-only Tapestry Collection boutique hotel","coords":"Exact official address checked 2026-08-28.","sources":["https://www.hilton.com/en/hotels/chqflup-chania-flair-boutique-hotel/","https://travel.hilton.com/en_us/articles/lgbtq-travel/"]},
 {"name":"Domus Renier Boutique Hotel","aliases":"Domus Renier Boutique Hotel|Domus Renier","city":"chania","description":"A sixteenth-century Venetian waterfront house reborn as a jewel-box hotel, with carved stone, contemporary art and balconies looking straight across Chania's old harbour.","vibe":"intimate Venetian romance at the centre of the harbour theatre","tags":"luxury,cultural,cozy","hours":"Reception schedule and late arrival require confirmation; breakfast and concierge vary.","link":"https://www.domusrenier.gr/","location":"Akti Kountourioti 41-42, Chania 73131, Greece","lat":35.51751,"lng":24.01613,"arrival":"Pedestrian harbour access and historic stairs demand precise luggage and mobility planning.","best":"Best for queer couples who want architectural romance steps from old-town evenings.","crowd":"LGBTQ+ couples mix with heritage travellers, honeymooners and design-focused guests.","dress":"Elegant island casual.","inclusion":"Included in current LGBTQ-welcoming Chania accommodation catalogues; no queer ownership is claimed.","basis":"Current specialist inclusion evidence paired with active first-party hotel details.","class":"Five-star independent historic boutique hotel","coords":"Exact official address checked 2026-08-28.","sources":["https://www.domusrenier.gr/","https://www.expedia.com/Chania-Hotels-LGBTQ-Welcoming-Hotel.0-0-d601135-tLGBTQWelcomingHotel.Travel-Guide-Filter-Hotels"]},
 {"name":"Casa Delfino Hotel & Spa","aliases":"Casa Delfino Hotel & Spa|Casa Delfino","city":"chania","description":"A family-owned Venetian mansion tucked into the old quarter, where a mosaic courtyard, rooftop views and a small hammam-like spa create grown-up sanctuary behind the harbour bustle.","vibe":"historic courtyard intimacy with rooftop-and-spa romance","tags":"luxury,cozy,relax","hours":"Reception operates daily; spa, rooftop and breakfast schedules vary.","link":"https://www.casadelfino.com/","location":"Theofanous 9, Chania 73100, Greece","lat":35.51670,"lng":24.01462,"arrival":"The car-free old town requires a porter or planned drop-off; confirm stairs and accessible-room limitations.","best":"Best for couples wanting privacy and character over a conventional resort.","crowd":"LGBTQ+ couples mix with heritage, culinary and romantic-break travellers.","dress":"Relaxed boutique elegance.","inclusion":"Longstanding specialist LGBTQ travel catalogues identify Casa Delfino as welcoming; no gay ownership claim is made.","basis":"Specialist inclusion evidence plus current direct property source.","class":"Five-star family-owned boutique hotel and spa","coords":"Exact official address checked 2026-08-28.","sources":["https://www.casadelfino.com/","https://www.travelgay.com/gay-chania-hotels"]},
 {"name":"Samaria Hotel","aliases":"Samaria Hotel|Samaria Hotel Chania","city":"chania","description":"A modern city hotel opposite the bus station with a shaded pool court and sharply run rooms, ideal when easy island transport matters more than harbour-postcard positioning.","vibe":"reliable central comfort with unusually practical island connections","tags":"cultural,relax,mixed","hours":"Reception operates 24 hours; pool, restaurant, gym and parking vary.","link":"https://www.samariahotel.gr/","location":"Kidonias 69, Chania 73135, Greece","lat":35.51193,"lng":24.01601,"arrival":"Bus-station traffic can be hectic; reserve parking, quiet room and adapted layout directly.","best":"Best for queer solo travellers and couples combining Chania with wider Crete exploration.","crowd":"LGBTQ+ travellers mix with business, tour, family and independent island guests.","dress":"Contemporary city casual.","inclusion":"Listed by current LGBTQ travel specialists as a welcoming Chania option; no dedicated queer programme is claimed.","basis":"Current specialist inclusion listing and active first-party property details.","class":"Four-star independent city hotel","coords":"Exact official address checked 2026-08-28.","sources":["https://www.samariahotel.gr/","https://www.travelgay.com/gay-chania-hotels"]},

 {"name":"The River Lee","aliases":"The River Lee|The River Lee Hotel","city":"cork","description":"A glassy riverside hotel with pool, health club and a genuinely lived-in lobby bar, positioned between University College Cork, Fitzgerald's Park and the compact queer centre.","vibe":"polished riverside social hotel balancing city energy and recovery","tags":"luxury,social,relax","hours":"Reception operates 24 hours; pool, gym, restaurant and bar use separate schedules.","link":"https://www.doylecollection.com/hotels/the-river-lee-hotel","location":"Western Road, Cork, Ireland","lat":51.89544,"lng":-8.48690,"arrival":"Event weekends pressure parking; confirm same-bed setup, adapted room and pool access before arrival.","best":"Best for Pride visitors wanting upscale facilities and a walkable route into the centre.","crowd":"LGBTQ+ couples and groups mix with university, business, arts and weekend guests.","dress":"Smart-casual in public rooms.","inclusion":"The Doyle Collection publishes diversity, equality and inclusive workplace commitments; no queer ownership claim.","basis":"Active first-party property plus current corporate responsibility evidence.","class":"Four-star luxury city hotel","coords":"Exact official address checked 2026-08-28.","sources":["https://www.doylecollection.com/hotels/the-river-lee-hotel","https://www.doylecollection.com/careers/diversity-and-inclusion"]},
