 {"name":"Imperial Hotel Cork","aliases":"Imperial Hotel Cork|The Imperial Hotel Cork|Imperial Hotel","city":"cork","description":"A grand South Mall landmark that layers historic staircases, a cocktail bar and Escape Spa into the most central possible base for Wilde, The Liberty and Pride routes.","vibe":"heritage city glamour with everything queer Cork in walking reach","tags":"luxury,cultural,relax","hours":"Reception operates 24 hours; spa, restaurants and bars require separate checks.","link":"https://www.imperialhotelcork.com/","location":"76 South Mall, Cork, T12 A2YT, Ireland","lat":51.89668,"lng":-8.47059,"arrival":"The historic footprint has varied rooms and steps; reserve adapted access, parking and preferred bedding directly.","best":"Best for first-time queer visitors prioritising walkability and old-city atmosphere.","crowd":"LGBTQ+ couples and Pride guests mix with wedding, business, heritage and spa visitors.","dress":"Polished city casual.","inclusion":"Included in current LGBTQ-welcoming Cork accommodation catalogues with an active official property source.","basis":"Current specialist inclusion evidence and first-party hotel information; no ownership claim.","class":"Four-star historic independent hotel","coords":"Exact official address checked 2026-08-28.","sources":["https://www.imperialhotelcork.com/","https://www.expedia.ie/Cork-Hotels-LGBTQ-Friendly-Hotel.0-0-d2692-tLGBTQFriendlyHotel.Travel-Guide-Filter-Hotels"]},
 {"name":"Maldron Hotel South Mall Cork City","aliases":"Maldron Hotel South Mall Cork City|Maldron South Mall|Maldron Hotel South Mall","city":"cork","description":"A contemporary South Mall base with straightforward rooms and a bright bar, designed for travellers who want predictable value a few minutes from Cork's queer venues.","vibe":"practical central comfort with zero-fuss nightlife access","tags":"mixed,cultural,cozy","hours":"Reception operates 24 hours; restaurant, breakfast and parking arrangements vary.","link":"https://www.maldronhotels.com/cork-south-mall/","location":"South Mall Street, Cork, T12 EE72, Ireland","lat":51.89707,"lng":-8.46696,"arrival":"There is limited on-site parking; confirm partner parking, adapted room and taxi drop-off.","best":"Best for value-conscious Pride visitors who want central walking and reliable service.","crowd":"LGBTQ+ solo guests and couples mix with business, event and short-break travellers.","dress":"Everyday city casual.","inclusion":"Dalata publishes diversity and inclusion commitments covering its Maldron workforce and guests.","basis":"Active first-party property paired with current group inclusion framework.","class":"Four-star Maldron city hotel","coords":"Exact official address checked 2026-08-28.","sources":["https://www.maldronhotels.com/cork-south-mall/","https://dalatahotelgroup.com/people-culture/diversity-inclusion/"]},

 {"name":"AC Hotel by Marriott Innsbruck","aliases":"AC Hotel by Marriott Innsbruck|AC Hotel Innsbruck|AC Innsbruck","city":"innsbruck","description":"A sleek central tower opposite the Triumphal Arch, with broad mountain views, sauna and an easy line between station, old town and Pride routes.","vibe":"modern alpine city base with panoramic recovery built in","tags":"luxury,relax,cultural","hours":"Reception operates 24 hours; sauna, gym, restaurant and parking vary.","link":"https://www.marriott.com/en-us/hotels/innac-ac-hotel-innsbruck/overview/","location":"Salurner Straße 15, 6020 Innsbruck, Austria","lat":47.26314,"lng":11.39458,"arrival":"Coach and congress traffic can crowd the forecourt; confirm adapted room, sauna access and same-bed setup.","best":"Best for queer couples wanting predictable international service and maximum walkability.","crowd":"LGBTQ+ couples and solo travellers mix with congress, rail, ski and city-break guests.","dress":"Clean modern casual.","inclusion":"Covered by Marriott's explicit global LGBTQ+ inclusion and equal-opportunity commitments.","basis":"Current corporate inclusion policy plus active first-party property information.","class":"Four-star AC Hotels city hotel","coords":"Exact official address checked 2026-08-28.","sources":["https://www.marriott.com/en-us/hotels/innac-ac-hotel-innsbruck/overview/","https://www.marriott.com/culture-and-values/diversity-and-inclusion.mi"]},
 {"name":"NALA Individuellhotel","aliases":"NALA Individuellhotel|NALA Hotel Innsbruck|Nala Individuellhotel","city":"innsbruck","description":"A wildly individual garden hotel where climbing greenery, mismatched art and cleverly compact rooms feel like an alpine design experiment hidden behind the centre.","vibe":"bohemian garden design hotel with private creative calm","tags":"cozy,cultural,relax","hours":"Reception and arrival procedures vary; garden, breakfast and fitness follow property schedules.","link":"https://www.nala-hotel.at/","location":"Müllerstraße 15, 6020 Innsbruck, Austria","lat":47.26189,"lng":11.39234,"arrival":"Room shapes differ substantially; confirm bed size, lift access, parking and late check-in.","best":"Best for queer design lovers wanting personality and a quiet garden after Pride.","crowd":"LGBTQ+ couples and solo guests mix with artists, sustainable travellers and city-break visitors.","dress":"Individual creative casual.","inclusion":"Current gay-friendly Tyrol hotel catalogues identify NALA as welcoming; no queer ownership is claimed.","basis":"Specialist regional inclusion evidence paired with active first-party hotel details.","class":"Four-star independent design hotel","coords":"Exact official address checked 2026-08-28.","sources":["https://www.nala-hotel.at/","https://www.tirol.ch/themen/gayfriendly-hotel"]},
 {"name":"Hotel Innsbruck","aliases":"Hotel Innsbruck|Hotel Innsbruck am Inn","city":"innsbruck","description":"A colourful spa hotel at the Inn Bridge, combining old-town immediacy with two wellness areas and rooftop mountain views for a surprisingly complete central retreat.","vibe":"old-town spa base with playful alpine colour","tags":"relax,cultural,luxury","hours":"Reception operates 24 hours; spa, pool, rooftop and dining use separate schedules.","link":"https://www.hotelinnsbruck.com/","location":"Innrain 3, 6020 Innsbruck, Austria","lat":47.26921,"lng":11.39258,"arrival":"The pedestrian old town and garage route need advance instructions; confirm adapted spa and room access.","best":"Best for Pride visitors who want DomCafe, the river and serious recovery within minutes.","crowd":"LGBTQ+ couples mix with wellness, ski, culture and international group guests.","dress":"Alpine city casual; robe rules in wellness areas.","inclusion":"Included in current regional gay-friendly hotel catalogues; no gay ownership or Pride partnership is asserted.","basis":"Current specialist inclusion signal plus active direct property evidence.","class":"Four-star independent spa hotel","coords":"Exact official address checked 2026-08-28.","sources":["https://www.hotelinnsbruck.com/","https://www.tirol.ch/themen/gayfriendly-hotel"]},
 {"name":"STAGE 12 Hotel by Penz","aliases":"STAGE 12 Hotel by Penz|STAGE 12|Stage 12 Innsbruck","city":"innsbruck","description":"A contemporary hotel carved into Maria-Theresien-Straße, pairing a dramatic garden terrace, sauna and mountain-facing rooms with the city's most effortless pedestrian location.","vibe":"sharp central design with a secret garden and alpine sauna","tags":"cultural,relax,social","hours":"Reception operates 24 hours; bar, breakfast, sauna and fitness schedules vary.","link":"https://www.stage12.at/en/","location":"Maria-Theresien-Straße 12, 6020 Innsbruck, Austria","lat":47.26629,"lng":11.39442,"arrival":"Pedestrian-zone access requires the published garage route; confirm adapted room and courtyard orientation.","best":"Best for queer travellers who want to step directly into Pride routes and old-town life.","crowd":"LGBTQ+ couples and friends mix with design, shopping, business and mountain guests.","dress":"Polished alpine casual.","inclusion":"Current LGBTQ-welcoming Innsbruck accommodation catalogues include the hotel; no queer ownership claim is made.","basis":"Current specialist inclusion evidence paired with active first-party property information.","class":"Four-star independent design hotel","coords":"Exact official address checked 2026-08-28.","sources":["https://www.stage12.at/en/","https://www.expedia.com/Innsbruck-Hotels-LGBTQ-Welcoming-Hotel.0-0-d6051204-tLGBTQWelcomingHotel.Travel-Guide-Filter-Hotels"]}
]
$qa_hotels$) h(name text,aliases text,city text,description text,vibe text,tags text,hours text,link text,location text,lat double precision,lng double precision,arrival text,best text,crowd text,dress text,inclusion text,basis text,class text,coords text,sources jsonb)
), hotels as (select h.*,string_to_array(h.tags,',')::text[] approved_tags,jsonb_build_object('queue_wait',arrival,'best_nights',best,'crowd_mix',crowd,'dress_code',dress,'staff_inclusivity',inclusion,'inclusion_basis',basis,'hotel_class',class,'coordinate_source',coords,'source_urls',sources,'research_status','current_inclusion_and_official_property_sources','updated_at','2026-08-28T00:00:00Z') intel from raw_hotels h), updated as (update public.places p set name=h.name,type='hotel',description=h.description,vibe=h.vibe,vibe_tags=h.approved_tags,hours=h.hours,link=h.link,location=h.location,lat=h.lat,lng=h.lng,venue_intel=coalesce(p.venue_intel,'{}'::jsonb)||h.intel,seo_indexable=true,seo_quality_status='approved',updated_at=timezone('utc',now()) from hotels h where lower(trim(p.city))=h.city and lower(trim(p.name)) in(select lower(trim(alias_name)) from unnest(string_to_array(h.aliases,'|')) alias_name) returning p.id)
insert into public.places(name,city,type,description,vibe,vibe_tags,hours,link,location,lat,lng,venue_intel,seo_indexable,seo_quality_status,updated_at) select h.name,h.city,'hotel',h.description,h.vibe,h.approved_tags,h.hours,h.link,h.location,h.lat,h.lng,h.intel,true,'approved',timezone('utc',now()) from hotels h where not exists(select 1 from public.places p where lower(trim(p.city))=h.city and lower(trim(p.name)) in(select lower(trim(alias_name)) from unnest(string_to_array(h.aliases,'|')) alias_name));

select public.qa_refresh_city_seo_status(slug) from (values('lille'),('corfu'),('chania'),('cork'),('innsbruck')) v(slug) where to_regprocedure('public.qa_refresh_city_seo_status(text)') is not null;

commit;

select lower(trim(city)) city,count(*) filter(where type='hotel') batch_hotel_count,count(*) filter(where type='hotel')=4 target_exactly_four
from public.places
where lower(trim(city)) in('lille','corfu','chania','cork','innsbruck')
  and lower(trim(name)) in(
    'moxy lille city','mama shelter lille','hôtel barrière lille','okko hotels lille centre',
    'gay corfu guesthouse','angsana corfu resort & spa','domes miramare, a luxury collection resort, corfu','cook''s club corfu',
    'chania flair boutique hotel, tapestry collection by hilton','domus renier boutique hotel','casa delfino hotel & spa','samaria hotel',
    'the river lee','the dean cork','imperial hotel cork','maldron hotel south mall cork city',
    'ac hotel by marriott innsbruck','nala individuellhotel','hotel innsbruck','stage 12 hotel by penz'
  )
group by lower(trim(city)) order by lower(trim(city));
